--- a/runtime/scheduler/scheduler_core.cc
+++ b/runtime/scheduler/scheduler_core.cc
@@ -412,6 +412,21 @@ void Scheduler::dispatch() {
+  // if affinity suggests co-scheduling, form a gang to amortize kernel costs
+  if (auto gang = gang_orchestrator_.try_form_gang(pending_queue_)) {
+    submit_gang(gang);
+    continue;
+  }
+
+  // existing dispatch path
   auto next = pending_queue_.pop();
   launch(next);
 }
